# Kaggle GPU job for "Le dernier tram" (generated by .github/workflows/tram.yml)
import os, subprocess, sys, time, glob, shutil
EP, FPS, SAMPLES, REPO = "__EP__", "__FPS__", "__SAMPLES__", "__REPO__"
KR = r'''__KR__'''
W = "/kaggle/working"; os.makedirs("/kaggle/tmp", exist_ok=True); os.chdir("/kaggle/tmp")
def sh(c): print("$", c, flush=True); return subprocess.call(c, shell=True)
sh("nvidia-smi --query-gpu=name --format=csv")
assert sh(f"wget -q https://raw.githubusercontent.com/{REPO}/main/bundles/{EP}.tar.gz -O b.tgz && tar xzf b.tgz") == 0
open("kr.py", "w").write(KR)
blender = None
for v in ["5.3.0", "5.3.1", "5.2.4"]:
    mm = ".".join(v.split(".")[:2])
    if sh(f"wget -q https://download.blender.org/release/Blender{mm}/blender-{v}-linux-x64.tar.xz -O bl.tar.xz && tar xf bl.tar.xz") == 0:
        blender = os.path.abspath(f"blender-{v}-linux-x64/blender"); print("Blender", v); break
assert blender
sh("apt-get -qq install -y libxkbcommon0 libsm6 libxi6 libxxf86vm1 libxfixes3 libxrender1 libgl1 >/dev/null 2>&1 || true")
t = time.time()
sh(f"{blender} -b --python kr.py -- {FPS} {SAMPLES} {EP} 2>&1 | grep -E 'DEVICES|FRAME|RENDER_DONE|rror|Traceback|File ' | tee {W}/render.log")
ff = shutil.which("ffmpeg")
if not ff:
    sh("pip install -q imageio-ffmpeg"); import imageio_ffmpeg; ff = imageio_ffmpeg.get_ffmpeg_exe()
out = f"{W}/{EP}_{FPS}fps_sans_son.mp4"
sh(f"{ff} -y -loglevel error -framerate {FPS} -i /kaggle/tmp/frames/%05d.jpg -c:v libx264 -preset slow -crf 18 -pix_fmt yuv420p -movflags +faststart {out}")
print("DONE", out, os.path.getsize(out) // 2**20, "MB", "%.1f min total" % ((time.time() - t) / 60), flush=True)
